const item = $input.first().json;
const rawBody= item.body;
const headers = item.headers || {};
const sizeBytes = Buffer.byteLength(rawBody, "utf8");
if (sizeBytes > 10240) {return[{json:{ok: false , error_code: "PAYLOAD_TOO_LARGE", _status: 413}}];} 
const idemkey = headers["idempotency-key"];
if (!idemkey) {return[{json:{ok: false, error_code: "MISSING_IDEMPOTENCY_KEY", _status: 400}}];}
const crypto = require("crypto");
const secret = $env.WEBHOOK_HMAC_SECRET;
if (!secret) {return[{json:{ok: false, error_code: "INTERNAL", _status: 500}}];}
const expected = crypto.createHmac("sha256", secret).update(rawBody).digest("hex");
const signature = headers["x-signature"];
let sigOK = false
if (signature && signature.length === expected.length) { try {
sigOK = crypto.timingSafeEqual(Buffer.from(signature, "hex"), Buffer.from(expected, "hex"))} catch(error) { sigOK = false;}}
if (!sigOK) {return[{json: {ok: false, error_code: "INVALID_SIGNATURE", _status: 401}}];}
return[{json: {ok: true, rawBody, idemkey }}];

const crypto = require("crypto");
const input = $input.first().json;
let payload;
try {payload = JSON.parse(input.rawBody)} catch (e) {
  return[{json: {ok: false, error_code: "VALIDATION_FAILED", message: "invalid JSON", _status: 422}}];
}
const trace_id = crypto.randomUUID();
for (const f of ["email", "full_name", "company"]) {
  if (typeof payload[f] !== "string" || payload[f].trim() === "") {
    return[{json: {ok: false, error_code: "VALIDATION_FAILED", message: "Missing field" + f , _status: 422}}];
  }
}
const email = payload.email.trim().toLowerCase();
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  return[{json: {ok: false, error_code: "VALIDTION_FAILED", message: "Bad email format", _status: 422}}];
}
const lead_id = crypto.createHash("sha256").update(email).digest("hex");
return[{json: {ok: true, trace_id: trace_id, lead_id: lead_id, normalized: {
  email: email,
  full_name: payload.full_name.trim(),
  company: payload.company.trim()
}, events: ["LeadReceived", "LeadValidated"]}}];
